mapper.select:
SELECT IFNULL(SUM(quantity), 0)
FROM sms_flash_promotion_order
WHERE member_id = #{memberId}
  AND flash_promotion_id = #{promotionId}
  AND flash_promotion_session_id = #{sessionId}
  AND product_id = #{productId}
  AND status IN (0, 1)

SELECT * FROM sms_flash_promotion_order
WHERE status = 0
  AND create_time < #{before}
ORDER BY create_time ASC
LIMIT #{limit}

SELECT COUNT(*)
FROM sms_flash_promotion_order
WHERE flash_promotion_id = #{promotionId}
  AND flash_promotion_session_id = #{sessionId}
  AND status = 1
